-- El historial no se edita ni se borra: lo garantiza la base, no solo la aplicación.
CREATE FUNCTION "historial_inmutable"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'El historial (%) no se edita ni se borra: corregilo con un ajuste o una anulación.', TG_TABLE_NAME USING ERRCODE = 'integrity_constraint_violation';
END
$$;
--> statement-breakpoint
CREATE TRIGGER "stock_movements_inmutable" BEFORE UPDATE OR DELETE ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION "historial_inmutable"();
--> statement-breakpoint
CREATE TRIGGER "sale_lines_inmutable" BEFORE UPDATE OR DELETE ON "sale_lines" FOR EACH ROW EXECUTE FUNCTION "historial_inmutable"();
--> statement-breakpoint
CREATE FUNCTION "venta_solo_se_anula"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Una venta no se borra: anulala para devolver el stock.' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.status <> 'registrada' OR NEW.status <> 'anulada'
     OR (to_jsonb(NEW) - 'status' - 'voided_at' - 'voided_by_email' - 'void_reason') <> (to_jsonb(OLD) - 'status' - 'voided_at' - 'voided_by_email' - 'void_reason') THEN
    RAISE EXCEPTION 'Una venta no se edita: lo único permitido es anularla una vez.' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "sales_solo_anulacion" BEFORE UPDATE OR DELETE ON "sales" FOR EACH ROW EXECUTE FUNCTION "venta_solo_se_anula"();
